import { supabase } from './client'

/**
 * tenant_memberships — source of truth for tenant access.
 * Schema (docs/schema-map.md): tenant_id, user_id, role (default 'member'),
 * status (default 'active'), unique (tenant_id, user_id).
 */
export type TenantMembership = {
  id: string
  tenant_id: string
  user_id: string
  role: string
  status: string
  joined_at: string | null
  invited_at: string | null
}

export const tenantMembershipsService = {
  async listForUser(userId: string): Promise<TenantMembership[]> {
    const { data, error } = await supabase
      .from('tenant_memberships')
      .select('id, tenant_id, user_id, role, status, joined_at, invited_at')
      .eq('user_id', userId)
    if (error) {
      console.warn('[tenantMemberships] listForUser failed:', error.message)
      return []
    }
    return (data ?? []) as TenantMembership[]
  },

  async listForTenant(tenantId: string): Promise<TenantMembership[]> {
    const { data, error } = await supabase
      .from('tenant_memberships')
      .select('id, tenant_id, user_id, role, status, joined_at, invited_at')
      .eq('tenant_id', tenantId)
      .order('joined_at', { ascending: false })
    if (error) {
      console.warn('[tenantMemberships] listForTenant failed:', error.message)
      return []
    }
    return (data ?? []) as TenantMembership[]
  },

  /**
   * Idempotent self-bootstrap: inserts only if no row exists for (tenant_id, user_id).
   * Never updates role/status on an existing row.
   */
  async ensure(input: { tenantId: string; userId: string; role?: string }): Promise<TenantMembership | null> {
    const existing = await supabase
      .from('tenant_memberships')
      .select('id, tenant_id, user_id, role, status, joined_at, invited_at')
      .eq('tenant_id', input.tenantId)
      .eq('user_id', input.userId)
      .maybeSingle()
    if (existing.data) return existing.data as TenantMembership
    const { data, error } = await supabase
      .from('tenant_memberships')
      .insert({
        tenant_id: input.tenantId,
        user_id: input.userId,
        role: input.role ?? 'member',
        status: 'active',
        joined_at: new Date().toISOString(),
      })
      .select('id, tenant_id, user_id, role, status, joined_at, invited_at')
      .single()
    if (error) {
      console.warn('[tenantMemberships] ensure insert failed:', error.message)
      return null
    }
    return data as TenantMembership
  },

  async invite(input: { tenantId: string; userId: string; role?: string }): Promise<TenantMembership | null> {
    const { data, error } = await supabase
      .from('tenant_memberships')
      .insert({
        tenant_id: input.tenantId,
        user_id: input.userId,
        role: input.role ?? 'member',
        status: 'pending',
        invited_at: new Date().toISOString(),
      })
      .select('id, tenant_id, user_id, role, status, joined_at, invited_at')
      .single()
    if (error) {
      console.warn('[tenantMemberships] invite failed:', error.message)
      return null
    }
    return data as TenantMembership
  },
}
